// Fresh actual dual constraints on complete first/second boundary Taylor basis.
#define main OldFirstJetMain
#include "firstjet_gate.cpp"
#undef main
J Basis(const hyp::LayerPoint<double>&p,int family){const J o=Power(p,1),y=Unit(p,1),z=Unit(p,2);switch(family){case 0:return J(D(1));case 1:return o;case 2:return y;case 3:return z;case 4:return o*o;case 5:return o*y;case 6:return o*z;case 7:return y*y;case 8:return y*z;default:return z*z;}}
std::array<double,8> LinearFormula(const Jet&u,const hyp::LayerPoint<double>&p,double a){std::array<double,8>out{};double ricci=0,lap=-3*u.chi.value.d/a;for(int i=0;i<3;++i){ricci+=2*u.chi.dd[i][i].d;for(int j=0;j<3;++j)ricci+=u.metric.ddg[i][j][i][j].d;}double contracted=.5*u.chi.d[0].d;for(int j=0;j<3;++j)contracted+=u.metric.dg[j][j][0].d;lap+=p.radius*contracted/a;const double G=p.radius*p.radius*(u.chi.value.d-u.metric.g[0][0].d)/(a*a);out[0]=p.omega*p.omega*ricci-4*(u.trace.value.d+2*u.theta.value.d)/a+4*p.omega*lap-6*G;for(int i=0;i<3;++i){double divA=0,divh=0;for(int j=0;j<3;++j){divA+=u.a.dk[j][j][i].d;divh+=u.metric.dg[j][j][i].d;}out[1+i]=p.omega*divA-2*(u.trace.d[i].d+2*u.theta.d[i].d)/3+2*p.radius*u.a.k[0][i].d/a;out[4+i]=.5*(u.lambda.value[i].d-divh);}out[7]=u.theta.value.d;return out;}
void Print8(const std::array<double,8>&v){std::cout<<'[';for(int i=0;i<8;++i)std::cout<<(i?",":"")<<v[i];std::cout<<']';}
std::array<double,20> Limit(const hyp::LayerReference<double>&ref,double a,int profile,int which){std::array<double,20>v{};const double weights[4]={4,-6,4,-1};for(int k=0;k<4;++k){const auto p=ref.At(std::sqrt(1-2*a*(k+1)*1e-4),0,0);Jet u=Lift(p.state);const auto o=Linear(Power(p,1));if(which==0){Seed(u,0,o);Seed(u,4,Linear(Power(p,1)*Unit(p,0)*J(D(-1))));}else if(which==1){Seed(u,0,o);}else Seed(u,2,Linear(Power(p,2)));Consistent(u);const auto rs=Parts(p,u,a,profile);for(int i=0;i<20;++i)v[i]+=weights[k]*(rs.r[i].d+rs.s[i].d/p.omega);}return v;}
int main(){double formula_error=0,m_identity=0,theta_identity=0;int formula_rows=0,identity_rows=0;std::cout<<std::setprecision(17)<<"{\"samples\":[";bool first=true;for(double a:{.5,.75,1.,2.}){hyp::LayerReference<double>ref(1,a,{true,.05,.95});for(double om:{0.,1e-4,1e-3,2e-3,4e-3}){const auto p=ref.At(std::sqrt(1-2*a*om),0,0);for(int family=0;family<10;++family)for(int col=0;col<20;++col){auto u=Lift(p.state);Seed(u,col,Linear(Basis(p,family)));Consistent(u);const auto actual=Constraints(u,p),formula=LinearFormula(u,p,a);for(int i=0;i<8;++i)formula_error=std::max(formula_error,std::abs(actual[i]-formula[i]));++formula_rows;if(!first)std::cout<<',';first=false;std::cout<<"{\"a\":"<<a<<",\"Omega\":"<<p.omega<<",\"family\":"<<family<<",\"col\":"<<col<<",\"C\":";Print8(actual);std::cout<<'}';}}}
std::cout<<"],\"compatible_identities\":[";first=true;for(double a:{.5,.75,1.,2.})for(int profile:{0,1})for(int trial=0;trial<20;++trial){hyp::LayerReference<double>ref(1,a,{true,.05,.95});const auto p=ref.At(1,0,0);auto u=First(p,trial);const auto gt=hyp::Geometry(u.metric),gb=hyp::Geometry(hyp::PenroseMetric(u.metric,u.chi));double H[3][3]{},tr=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j){H[i][j]=u.metric.g[i][j].d+gb.connection[0][i][j].d;if(i==j)tr+=H[i][j];}for(int i=0;i<3;++i)H[i][i]-=tr/3;const double P1=.1*std::cos((trial+1)*4.),T1=.1*std::cos((trial+1)*5.);std::array<double,3>lambda{};std::array<std::array<double,3>,3>A{};const double d[3]={(12*H[0][0]+4*P1+2*T1)/(30*a*a+2),4*H[0][1]/(10*a*a),4*H[0][2]/(10*a*a)};for(int i=0;i<3;++i){lambda[i]=gt.contracted[i].d+d[i];for(int j=0;j<3;++j)A[i][j]=H[i][j]-.5*((i==0?d[j]:0)+(j==0?d[i]:0)-(i==j?2*d[0]/3:0));}u=First(p,trial,&lambda,&A);const auto c=Constraints(u,p);double h1=0,tdot=0;const double ex[4]={4,-6,4,-1};for(int k=0;k<4;++k){const double om=(k+1)*1e-4;const auto pp=ref.At(std::sqrt(1-2*a*om),0,0);const auto uu=First(pp,trial,&lambda,&A);const auto cc=Constraints(uu,pp);const auto rs=Parts(pp,uu,a,profile);h1+=ex[k]*cc[0]/pp.omega;tdot+=ex[k]*(rs.r[3].d+rs.s[3].d/pp.omega);}for(int i=0;i<3;++i)m_identity=std::max(m_identity,std::abs(c[1+i]-(a*10-2/a)*c[4+i]-(i==0?T1/a:0)));const double k2=profile?2/(10*a*a)-1:0,expected=h1/(2*a)+(4/(a*a)-10*(2+k2))*T1;theta_identity=std::max(theta_identity,std::abs(tdot-expected));++identity_rows;if(!first)std::cout<<',';first=false;std::cout<<"{\"a\":"<<a<<",\"profile\":"<<profile<<",\"trial\":"<<trial<<",\"H1\":"<<h1<<",\"Theta1\":"<<T1<<",\"Theta_t0_actual\":"<<tdot<<",\"Theta_t0_expected\":"<<expected<<"}";}
std::cout<<"],\"Einstein_gauge_corners\":[";first=true;for(double a:{.5,.75,1.,2.})for(int profile:{0,1})for(int which:{0,1,2}){hyp::LayerReference<double>ref(1,a,{true,.05,.95});const auto p=ref.At(1,0,0);auto u=Lift(p.state);if(which<=1){Seed(u,0,Linear(Power(p,1)));if(which==0)Seed(u,4,Linear(Power(p,1)*Unit(p,0)*J(D(-1))));}else Seed(u,2,Linear(Power(p,2)));Consistent(u);const auto rs=Parts(p,u,a,profile);double pole=0;for(auto f:rs.s)pole=std::max(pole,std::abs(f.d));const auto F=Limit(ref,a,profile,which);const double wdot=F[0]+F[4],Ndot=(F[1]-F[7])/(a*a)+2*wdot/a,Qnumdot=F[2]-3*wdot;if(!first)std::cout<<',';first=false;std::cout<<"{\"a\":"<<a<<",\"profile\":"<<profile<<",\"which\":"<<which<<",\"R0_max\":"<<pole<<",\"C0\":";Print8(Constraints(u,p));std::cout<<",\"F0\":[";for(int i=0;i<20;++i)std::cout<<(i?",":"")<<F[i];std::cout<<"],\"Nraw_t0\":"<<Ndot<<",\"Qnumerator_t0\":"<<Qnumdot<<"}";}
std::cout<<"],\"summary\":{\"formula_rows\":"<<formula_rows<<",\"actual_constraint_formula_max_error\":"<<formula_error<<",\"identity_rows\":"<<identity_rows<<",\"R0_compatible_M0_Z0_Theta1_error\":"<<m_identity<<",\"Theta_t0_H1_Theta1_error\":"<<theta_identity<<"}}\n";}
